INSERT IGNORE INTO edu_quiz_question(id,section_id,question,option_a,option_b,option_c,option_d,correct_option,explanation) VALUES
 (5101,2103,'订单库存最终确认更适合放在哪里？','浏览器','MySQL条件更新','图片服务','DNS','B','最终库存扣减必须由数据库条件更新兜底。'),
 (5102,2203,'Agent遇到工具失败时首先应该保留什么？','工具错误和上下文','用户密码','数据库连接串','页面颜色','A','错误信息和上下文用于重试、降级或向用户解释。'),
 (5103,2303,'Spring事务通常应该放在哪一层？','Controller','Service','DTO','前端页面','B','Service层更容易覆盖一个完整的业务事务边界。'),
 (5104,2403,'定位慢查询最先应该查看什么？','执行计划','头像图片','浏览器缓存','日志颜色','A','执行计划可以判断索引、扫描行数和连接方式。'),
 (5105,2503,'缓存击穿常见的保护方式是什么？','热点Key互斥重建','删除数据库','关闭缓存','增加前端按钮','A','热点Key失效时通过互斥重建避免大量请求同时打到数据库。'),
 (5106,2603,'RabbitMQ中决定消息进入哪个队列的关键组件是什么？','交换机和路由键','数据库索引','JWT','CSS','A','生产者把消息发给交换机，交换机按路由键绑定到队列。'),
 (5107,2703,'向量检索前通常需要先做什么？','文本向量化','关闭网络','删除原文','修改密码','A','文本需要通过Embedding模型转换为向量后才能进行相似度检索。'),
 (5108,2803,'FastAPI中用于请求参数校验的常见组件是什么？','Pydantic模型','RabbitMQ交换机','MySQL触发器','视频播放器','A','Pydantic模型负责请求和响应数据校验。'),
 (5109,2903,'评估集的主要作用是什么？','比较版本质量变化','提高屏幕分辨率','生成订单号','管理库存','A','固定问题集可以用于回归比较模型或提示词版本。'),
 (5110,3003,'服务拆分前最重要的依据是什么？','业务边界和团队协作','类名长度','图片尺寸','用户头像','A','拆分应建立在清晰的业务边界和独立演进需求上。');
